const items = $input.all();

const reviews = items
  .map((item, index) => ({
    review_id: item.json.review_id || `row_${index + 1}`,
    review_text: String(item.json.review_text ?? "").trim(),
    rating: item.json.rating ?? null,
    review_date: item.json.review_date ?? null
  }))
  .filter(review => review.review_text.length > 0);

const analysisInput = {
  product: "Groww",
  total_reviews: reviews.length,
  analysis_focus: [
    "Customer sentiment",
    "Recurring product issues",
    "App performance and usability",
    "Trading and investing experience",
    "Brokerage fees and other charges",
    "Frequently misunderstood fees or charges",
    "Suggested product improvements"
  ],
  reviews: reviews
};

return [
  {
    json: {
      ...analysisInput,
      reviews_json: JSON.stringify(analysisInput)
    }
  }
];

const input = $input.first().json;
const reviews = input.reviews;

const batchSize = 50;
const batches = [];

for (let i = 0; i < reviews.length; i += batchSize) {
  const batch = reviews.slice(i, i + batchSize);

  batches.push({
    json: {
      product: "Groww",
      batch_number: Math.floor(i / batchSize) + 1,
      total_batches: Math.ceil(reviews.length / batchSize),
      review_count: batch.length,
      reviews_json: JSON.stringify({
        product: "Groww",
        reviews: batch
      })
    }
  });
}

return batches;

