=
Analyse the following Groww customer reviews:

{{ $json.reviews_json }}

parameters.jsCode:
const items = $input.all();

// Get the original batch of 50 reviews
const originalBatch = $("TEST - Limit to One Branch").first().json;

const originalReviews = JSON.parse(
  originalBatch.reviews_json
).reviews;

// Allowed classification values
const allowedSentiments = [
  "positive",
  "negative",
  "mixed_or_neutral"
];

const allowedThemes = [
  "brokerage_fees",
  "other_charges",
  "fee_explanation_confusion",
  "app_performance",
  "usability",
  "trading_experience",
  "account_access",
  "customer_support",
  "other"
];

// Get original review IDs
const originalIds = originalReviews.map(
  r => String(r.review_id)
);

const originalIdSet = new Set(originalIds);
const allClassifications = [];

// Read and parse OpenAI responses
for (const item of items) {
  const rawText = item.json.output?.[0]?.content
    ?.filter(part => part.type === "output_text")
    .map(part => part.text)
    .join("");

  if (!rawText) {
    throw new Error("OpenAI returned no text");
  }

  const cleaned = rawText
    .replace(/^\s*```(?:json)?\s*/i, "")
    .replace(/\s*```\s*$/, "")
    .trim();

  let analysis;

  try {
    analysis = JSON.parse(cleaned);
  } catch (error) {
    throw new Error(
      "Invalid AI JSON: " + error.message
    );
  }

  if (!Array.isArray(analysis.reviews)) {
    throw new Error("AI response has no reviews array");
  }

  allClassifications.push(...analysis.reviews);
}

// Check review IDs
const returnedIds = allClassifications.map(
  r => String(r.review_id)
);

const returnedIdSet = new Set(returnedIds);

const missingIds = originalIds.filter(
  id => !returnedIdSet.has(id)
);

const unexpectedIds = returnedIds.filter(
  id => !originalIdSet.has(id)
);

// Check classification values
const invalidReviews = allClassifications.filter(r =>
  !allowedSentiments.includes(r.sentiment) ||
  !Array.isArray(r.themes) ||
  r.themes.some(t => !allowedThemes.includes(t)) ||
  typeof r.fee_confusion !== "boolean"
);

// Calculate sentiment totals
const sentiment = {
  positive: 0,
  negative: 0,
  mixed_or_neutral: 0
};

for (const review of allClassifications) {
  if (allowedSentiments.includes(review.sentiment)) {
    sentiment[review.sentiment]++;
  }
}

// Count reviews flagged for fee confusion
const feeConfusionCount = allClassifications.filter(
  r => r.fee_confusion === true
).length;

// Create a lookup of original review texts
const originalReviewMap = new Map(
  originalReviews.map(r => [
    String(r.review_id),
    r.review_text
  ])
);

// Create fee confusion audit
const feeConfusionAudit = allClassifications
  .filter(r => r.fee_confusion === true)
  .map(r => ({
    review_id: r.review_id,
    original_review: originalReviewMap.get(
      String(r.review_id)
    ) ?? "Review not found",
    sentiment: r.sentiment,
    themes: r.themes,
    fee_confusion: r.fee_confusion
  }));

// Check whether structural validation passed
const validationPassed =
  allClassifications.length === originalReviews.length &&
  returnedIdSet.size === originalIdSet.size &&
  missingIds.length === 0 &&
  unexpectedIds.length === 0 &&
  invalidReviews.length === 0;

// Return validated analysis and audit
return [{
  json: {
    product: "Groww",
    batch_number: originalBatch.batch_number,
    expected_review_count: originalReviews.length,
    classifications_returned: allClassifications.length,
    unique_review_ids: returnedIdSet.size,
    missing_review_ids: missingIds,
    unexpected_review_ids: unexpectedIds,
    invalid_classifications: invalidReviews.length,
    validation_passed: validationPassed,
    sentiment_summary: sentiment,
    fee_confusion_count: feeConfusionCount,
    fee_confusion_audit: feeConfusionAudit,
    reviews: allClassifications
  }
}];

const data = $input.first().json;

if (data.validation_passed !== true) {
  throw new Error("Cannot aggregate invalid classifications");
}

const reviews = data.reviews;

const sentimentCounts = {
  positive: 0,
  negative: 0,
  mixed_or_neutral: 0
};

const themeCounts = {};

for (const review of reviews) {
  sentimentCounts[review.sentiment]++;

  for (const theme of new Set(review.themes)) {
    themeCounts[theme] = (themeCounts[theme] || 0) + 1;
  }
}

const topThemes = Object.entries(themeCounts)
  .map(([theme, count]) => ({
    theme,
    count
  }))
  .sort((a, b) => b.count - a.count);

const feeConfusionReviews = reviews.filter(
  r => r.fee_confusion === true
);

return [{
  json: {
    product: "Groww",
    analysis_scope: "First 50 reviews - test batch",
    reviews_analyzed: reviews.length,
    sentiment_summary: sentimentCounts,
    theme_summary: topThemes,
    fee_confusion_count: feeConfusionReviews.length,
    fee_confusion_review_ids: feeConfusionReviews.map(
      r => r.review_id
    ),
    validation_passed: true
  }
}];

