const item = $input.first().json;

// Handle both possible OpenAI output structures
const content = item.output?.[0]?.content ?? item.content ?? [];

const rawReport = content
  .filter(part => part.type === "output_text")
  .map(part => part.text)
  .join("\n");

if (!rawReport) {
  throw new Error("Weekly Product Pulse text not found");
}

// Remove an unsupported claim about fee dissatisfaction
const report = rawReport.replace(
  /- \*\*Dissatisfaction with high fees\*\*:.*(?:\r?\n|$)/g,
  ""
).trim();

return [{
  json: {
    product: "Groww",
    report_type: "Weekly Product Pulse",
    analysis_scope: "First 50 reviews - test batch",
    report_markdown: report,
    status: "Draft - awaiting approval"
  }
}];

const data = $input.first().json;

if (data.validation_passed !== true) {
  throw new Error("Review classifications have not passed validation");
}

const feeReviews = data.fee_confusion_audit || [];

return [{
  json: {
    product: "Groww",
    analysis_scope: "First 50 reviews - test batch",
    reviews_analyzed: data.expected_review_count,
    fee_confusion_count: feeReviews.length,
    fee_confusion_evidence: feeReviews,
    status: "Evidence prepared - fee policy verification required"
  }
}];

